SELECT id, api_code, api_name, api_type, method, url, content_type, status FROM wf_api_catalog WHERE del_flag = 0 AND status = 1
AND (
api_code LIKE CONCAT('%', #{kw}, '%') OR api_name LIKE CONCAT('%', #{kw}, '%') OR url LIKE CONCAT('%', #{kw}, '%')
)
ORDER BY create_time DESC LIMIT #{limit}

SELECT id, flow_code, flow_name, trigger_type, trigger_config, execution_mode, graph_json, status FROM wf_flow_definition WHERE del_flag = 0 AND status = 1
AND (
flow_code LIKE CONCAT('%', #{kw}, '%') OR flow_name LIKE CONCAT('%', #{kw}, '%')
)
ORDER BY create_time DESC LIMIT #{limit}

SELECT id, ds_code, ds_name, db_type, status FROM wf_datasource WHERE del_flag = 0 AND status = 1
AND (
ds_code LIKE CONCAT('%', #{kw}, '%') OR ds_name LIKE CONCAT('%', #{kw}, '%')
)
ORDER BY create_time DESC LIMIT #{limit}
